from pathlib import Path
import json,hashlib
B=Path(__file__).resolve().parent;S=B.parents[1];R=B/'preview001';R.mkdir(exist_ok=True);sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();receipt=json.loads((B/'source001/qa/REOPEN_RECEIPT.json').read_text());assert receipt['status']=='PASS_INDEPENDENT_REOPEN_EXACT_SOURCE_OBJECTS_MATERIALS_UV'
source=B/'source001/source/AST-AQU-016_east_gallery_canopy_r02.blend';assert sha(source)==receipt['source_sha256'];plan=json.loads((B/'CORE_PLAN.json').read_text())
proposal={'status':'PASS_SOURCE_PREVIEW_OPTICAL_PLAN','source_sha256':sha(source),'view':{'eye_xyz':[-14,54.15,-443.2],'target_xyz':[-9.4,54.3,-449.4],'vertical_fov_degrees':72,'basis':'Exact same standing pose as installed image criticized by user'},'fixtures':[dict(r,source_preview_power_watts=385,half_angle_degrees=55,preview_shadow_soft_size_m=.02)for r in plan['fixture_reservations']],'scope':'Source geometry study; same current0.55native energy represented only by existing700W source-preview mapping, not a brightness-equivalence or native acceptance.'}
(R/'LIGHT_PROPOSAL.json').write_text(json.dumps(proposal,indent=2)+'\n')
s=(S/'pool-opposite-gallery-proposal001/combined_source002/source_light_view002/render.py').read_text();s=s.replace('scene.cycles.samples=32','scene.cycles.samples=16').replace("candidate=HERE.parent/'source/AST-AQU-016_east_gallery_composed.blend'","candidate=HERE.parent/'source001/source/AST-AQU-016_east_gallery_canopy_r02.blend'").replace("assert sha(candidate)=='9aa232ad30c515eabb128804b6d430ae2cfc3d76f93383a612165281620e6f05'","assert sha(candidate)=='"+sha(source)+"'").replace("planpath=HERE.parent/'preview_light_plan001/LIGHT_PROPOSAL.json'","planpath=HERE/'LIGHT_PROPOSAL.json'").replace('upper_gallery_source_light_study.png','upper_gallery_canopy_corrected_source_study.png');(R/'render.py').write_text(s)
pins=json.loads((S/'pool-opposite-gallery-proposal001/combined_source002/source_light_view002/PREVIEW_PINS.json').read_text());pins={'sha256':{p:h for p,h in pins['sha256'].items()if 'combined_source002'not in p}};pins['sha256'].update({str(p):sha(p)for p in [source,R/'LIGHT_PROPOSAL.json',R/'render.py',B/'source001/qa/REOPEN_RECEIPT.json',B/'ACTUAL_CORE_REVIEW.json']});(R/'PREVIEW_PINS.json').write_text(json.dumps(pins,indent=2)+'\n')
s=(S/'pool-opposite-gallery-proposal001/combined_source002/source_light_view002/run.py').read_text().replace("S.parent/'qa/INDEPENDENT_REOPEN.json'","S.parent/'source001/qa/REOPEN_RECEIPT.json'").replace('PASS_EXACT_COMPOSED_SOURCE_REOPEN','PASS_INDEPENDENT_REOPEN_EXACT_SOURCE_OBJECTS_MATERIALS_UV').replace('upper_gallery_source_light_study.png','upper_gallery_canopy_corrected_source_study.png')
s=s.replace("try:\n start=time.monotonic()","for key,name in [('XDG_CONFIG_HOME','config'),('XDG_DATA_HOME','data'),('XDG_CACHE_HOME','cache'),('TMPDIR','tmp')]:p=S/name;p.mkdir();env[key]=str(p)\ntry:\n start=time.monotonic()")
(R/'run.py').write_text(s);print('Prepared same-angle source view',sha(R/'run.py'))
